  var COLOR_SKI_LODGE           = 0x886655;
  var COLOR_CABLE_STATION       = 0x556655;
  var COLOR_CHALET              = 0x776644;
  var COLOR_SURVIVOR            = 0x886655;
  var COLOR_LOOTER              = 0x443322;
