  var _glassDomes = [];

  /* ── Oxygen bubbles (atmosphere VFX) ─────────────────────────────────── */
  var _bubbles = [];

  /* ── Toxic cloud (Lab B chem) ────────────────────────────────────────── */
  var _toxicClouds = [];
  /* each: { mesh, light, life } */

  /* ── Sonic pulse VFX ─────────────────────────────────────────────────── */
  var _sonicPulses = [];
