  // Timing
  var gameTime = 0;
  var maxTime = 900; // 15 minutes
  var heloTime = 720; // 12 minutes
  var heloArrived = false;
  var gameOver = false;
  var gameWon = false;

  // Player state
  var playerHP = 100;
  var playerPos = null;
  var playerDir = null;
  var radioCapturing = false;
  var radioHoldTime = 0;
  var radioCaptured = false;
  var radioTransmitted = false;
  var extracted = false;

  // Key tracking for activation
  var keysDown = {};
  var keyTimes = {};
  var gPressed = false;
  var wPressed = false;

  // Game objects
  var trees = [];
  var bushes = [];
