    _mouseDown   = false;
    _playerPos   = null;
    _inTruck     = false;
    _vats        = [];
    _laptop      = null;
    _laptopLight = null;
    _c4Vat       = null;
    _c4PlantTimer = 0;
    _eHeld       = false;
    _intelHoldTime = 0;
