    movePlayer(dt);

    /* Charge planting / terminal interaction */
    tryPlantCharge(dt);

    /* Enemies */
    updateGuards(dt);
    updateEngineers(dt);
    updateBoss(dt);

    /* Bullets */
    updatePlayerBullets(dt);
    updateEnemyBullets(dt);

    /* Toxic gas */
    updateToxicGas(dt);

    /* Detonation countdown */
    updateDetonation(dt);

    /* Environment */
    updateConveyor(dt);
    updateEscapeMarker(dt);

    /* VFX */
    updateExplosions(dt);
    updateDebris(dt);

