    _envLights     = [];
    _reactors      = [];
    _guards        = [];
    _engineers     = [];
    _boss          = null;
    _drums         = [];
    _conveyorItems = [];
    _gasParticles  = [];
    _playerBullets = [];
    _enemyBullets  = [];
    _explosions    = [];
    _debris        = [];
    _fireParticles = [];
    _playerMesh    = null;
    _terminalMesh  = null;
    _escapeMesh    = null;

    /* Reset state */
    _playerHP        = 100;
    _chargesPlanted  = 0;
    _reactorCharged  = [false, false, false, false];
    _detonationArmed = false;
    _detonationTimer = 0;
    _escapeActive    = false;
    _toxicGasActive  = false;
    _gasVentActive   = false;
    _terminalInteract = false;
    _ventTimer       = 0;
    _plantingCharge  = false;
    _plantTimer      = 0;
    _plantTarget     = -1;
    _eHeld           = false;
    _fireCooldown    = 0;
    _missionTimer    = 0;

