    for (var s = 0; s < 8; s++) {
      addBox(5, 0.35, 0.15, 0xaaaaaa, -15, 0.2 + s * 0.38, 39.8);
      addBox(5, 0.35, 0.15, 0xaaaaaa, 15, 0.2 + s * 0.38, 39.8);
    }
