    addBox(scene, 0.12, 0.12, 10, 0x8b7355, 16, 2.5, -62);
    // Anchor port (decorative hole area)
    addBox(scene, 1.5, 1.5, 0.2, 0x223344, 25, 1, -73);

    // ── Depth charge rack (stern) ──
