      _add(ring);
      /* MG tripod */
      var mgBody = _makeBox(0.5, 0.8, 1.2, 0x444444, nd.x, 1.4, nd.z);
      _add(mgBody);
      var mgBarrel = _makeBox(0.2, 0.2, 2.0, 0x333333, nd.x, 1.6, nd.z - 1.5);
