    _objects          = [];
    _enemies          = [];
    _hedgehogs        = [];
    _rockets          = [];
    _mgBullets        = [];
    _patrolBoat       = null;
    _siloTerminal     = null;
    _siloTerminalPos  = null;
    _daxEnemy         = null;
    _fountainParts    = [];
    _radarParts       = [];
    _mgNests          = [];
    _extractionDock   = null;
    _iPressed         = false;
    _fPressed         = false;
    _iTime            = 0;
    _fTime            = 0;
    _elapsed          = 0;
    _beachPhase       = true;
    _mgTimer          = 0;
    _missileTimer     = 0;
    _missileLaunched  = false;
    _gameOver         = false;
    _gameWon          = false;
    _playerHP         = 100;
    _playerCrouching  = false;
    _nearHedgehog     = false;
    _nearSiloTerminal = false;
    _siloInteractProgress = 0;
    _eHeld            = false;
    _launchDestroyed  = false;
    _daxDefeated      = false;
    _reachedDock      = false;
