    state.scene = new THREE.Scene();
    state.scene.background = new THREE.Color(0x99BBCC);
    state.scene.fog = new THREE.FogExp2(0x99BBCC, 0.018);

    state.camera = new THREE.PerspectiveCamera(75, w / h, 0.1, 800);
