    var torch1 = new THREE.PointLight(0xff8800, 1.2, 20);
    torch1.position.set(-5, 8, -8);
    scene.add(torch1);
    var torch2 = new THREE.PointLight(0xff8800, 0.8, 15);
    torch2.position.set(0, 8, -32);
    scene.add(torch2);
