    _time       = 0;
    _allMeshes  = [];
    _chainLines = [];
    _derrickParts = [];
    _pipeParts  = [];
    _fireParts  = [];
    _flareStack = null;
    _flareLight = null;
    _ocean      = null;
    _enemies    = [];
    _hostages   = [];
    _detonator  = null;
    _eHolding   = false;
    _eTimer     = 0;
    _keys       = {};
    _px = 0; _py = PLATFORM_Y + 1.7; _pz = 20;
