  var enemies = [];
  var dataDrives = [];
  var snowParticles = [];
  var buildings = [];
  var beaconLight;
  var beaconTime = 0;
  var drivesCollected = 0;
  var selfDestructActive = false;
  var selfDestructTimer = 0;
  var selfDestructDuration = 10;
