    addMesh(box(12, 3, 0.4, 0xCC1111, -20, 1.5, TRACK_RZ + 12));
    addMesh(box(12, 3, 0.4, 0x1111CC, 20,  1.5, TRACK_RZ + 12));
    addMesh(box(12, 3, 0.4, 0xCC9900, -20, 1.5, -TRACK_RZ - 12));
