      'position:fixed',
      'top:80px',
      'left:50%',
      'transform:translateX(-50%)',
      'background:rgba(0,40,20,0.85)',
      'color:#00ff88',
      'font-family:monospace',
      'font-size:16px',
      'padding:6px 16px',
      'border:1px solid #00aa55',
      'border-radius:4px',
