    // Engines
    var egeo = new THREE.CylinderGeometry(1.2, 1.4, 6, 8);
    var em1 = makeMesh(egeo, mat(0x888888));
    em1.rotation.x = Math.PI / 2;
    em1.position.set(-13, -1.5, 3);
