      railPoints.push(rx, 4.15, -1.2,  rx, 4.15, -1.2);
      railPoints.push(rx, 4.15, 1.2,   rx, 4.15, 1.2);
      // post
      railPoints.push(rx, 4.15, -1.2,  rx, 5.2, -1.2);
