      chunk.rotation.set(
        Math.random() * Math.PI,
        Math.random() * Math.PI,
        Math.random() * Math.PI
      );
      addToScene(chunk);
      debrisChunks.push(chunk);
      debrisRotSpeeds.push({
        rx: 0.1 + Math.random() * 0.5,
        ry: 0.1 + Math.random() * 0.5,
        rz: 0.1 + Math.random() * 0.5
      });
