      arm.position.set(0, 0.6, 0);
      arm.rotation.x = Math.PI / 2;
      group.add(arm);

      // dish (cone as dish approximation)
      dish = makeCone(0.8, 0.5, 8, 0x667788);
      dish.position.set(0, 0.6, 1.2);
      dish.rotation.x = -Math.PI / 2;
      group.add(dish);

