    var headGeometry = new THREE.SphereGeometry(0.8, 16, 16);
    var headMaterial = new THREE.MeshStandardMaterial({ color: 0x5A5450, roughness: 0.85 });
    var head = new THREE.Mesh(headGeometry, headMaterial);
