        var rackGeometry = new THREE.BoxGeometry(rackWidth, rackHeight, rackDepth);
        var rack = new THREE.Mesh(rackGeometry, rackMaterial);
        rack.position.set(
          -2.5 + (col * (rackWidth + rackSpacing)),
          rackHeight / 2,
          -3 + (row * (rackDepth + rackSpacing))
        );
        rack.castShadow = true;
