    var col1 = createCrumblingColumn(-12, -8);
    scene.add(col1);
    ruinObjects.push(col1);

    var col2 = createCrumblingColumn(12, -8);
    scene.add(col2);
    ruinObjects.push(col2);

    var col3 = createCrumblingColumn(-8, 5);
    scene.add(col3);
    ruinObjects.push(col3);

