		var material = new THREE.MeshPhongMaterial({ color: color });
		var mesh = new THREE.Mesh(geometry, material);
		mesh.position.set(x, y, z);
		if (rx) mesh.rotation.x = rx;
		if (ry) mesh.rotation.y = ry;
		if (rz) mesh.rotation.z = rz;
