		for (var i = 0; i < 8; i++) {
			var xPos = -40 + i * 12;
			var sprinklerHead = createCylinder(0.2, 0.2, 1, COLORS.warning_yellow, xPos, 13.8, 0);
			sprinklerHead.name = 'sprinklerHead_' + i;
		}

		// Additional industrial details
		createBox(0.5, 4, 0.5, COLORS.steel, -45, 2, 0);
