		createBox(0.5, 4, 0.5, COLORS.steel, -45, 2, 20);
		createBox(0.5, 4, 0.5, COLORS.steel, 45, 2, -20);

		// Emergency lighting
		createCylinder(0.3, 0.3, 0.2, COLORS.warning_yellow, -40, 14, 35);
