		var pointLight1 = new THREE.PointLight(0xffffff, 0.6);
		pointLight1.position.set(-30, 8, 0);
		scene.add(pointLight1);

		var pointLight2 = new THREE.PointLight(0xffffff, 0.6);
		pointLight2.position.set(30, 8, 0);
