    state.dishes = [];
    state.uplinkTower = null;
    state.signalRoom = null;
    state.vault = null;
    state.satelliteDisplay = null;
    state.radarDomes = [];
    state.generators = [];
    state.fence = null;
    state.weatherStation = null;
    state.siloCovers = [];
    state.quarters = null;
    state.briefingTheater = null;
