            var time = performance.now() * 0.0005;
            ghost.position.y += Math.sin(time * ghost.userData.speed + ghost.userData.offset) * delta * 2;
            ghost.position.x += Math.cos(time * ghost.userData.speed * 0.7 + ghost.userData.offset) * delta;
