            var wallMaterial = new THREE.MeshLambertMaterial({ color: mossGreen });
            var wall = new THREE.Mesh(wallGeometry, wallMaterial);
            wall.position.set(30 + i * 5, 3, -25 - i * 3);
            wall.castShadow = true;
            wall.receiveShadow = true;
            scene.add(wall);
