        var tunnelGeometry = new THREE.CylinderGeometry(2.5, 2.5, 15, 8);
        var tunnel = new THREE.Mesh(tunnelGeometry, exitTunnelMaterial);
        tunnel.position.set(exitX, 4, exitZ);
