            var pitGeo = new THREE.BoxGeometry(20, 3, 20);
            var pitMat = new THREE.MeshLambertMaterial({ color: 0x1a1a1a });
            var pitMesh = new THREE.Mesh(pitGeo, pitMat);
            pitMesh.position.set(x, 1.5, z);
