            fog.position.set((Math.random() - 0.5) * 200, Math.random() * 3, (Math.random() - 0.5) * 200);
            fog.userData.vx = (Math.random() - 0.5) * 0.02;
            fog.userData.vz = (Math.random() - 0.5) * 0.02;
            scene.add(fog);
            objects.push(fog);
            fogSpheres.push(fog);
