        var beachGeom = new THREE.BoxGeometry(200, 2, 60);
        var beachMat = new THREE.MeshLambertMaterial({ color: 0xCDB892 });
        var beach = new THREE.Mesh(beachGeom, beachMat);
        beach.position.set(0, 0.5, -30);
