            // Main drill pipe - cylinder
            var drillGeometry = new THREE.CylinderGeometry(1.5, 1.5, 30, 10);
            var drill = new THREE.Mesh(drillGeometry, drillMaterial);
            drill.position.set(rigX, 15, rigZ);
