            forkMesh1.position.set(vx - 1, 2, vz + 5);
            scene.add(forkMesh1);
            objects.push(forkMesh1);

            var forkMesh2 = new THREE.Mesh(forkGeom, forkMaterial);
            forkMesh2.position.set(vx + 1, 2, vz + 5);
